-- İstanbul uzun açıklamaları, 3. parti (10 yer, TR + EN).
-- Üreten: data-pipeline/content/build_long_desc.py (kaynak: content/istanbul_long_descriptions.py).
-- Metinler kendi cümlelerimizdir; Vikipedi/Wikidata yalnızca bilgi kontrolü için kullanıldı.

update public.place_translations t
   set long_desc = v.long_desc
  from (values
  ('sokollu-mehmed-pasa-camii', 'tr', 'Üç padişaha sadrazamlık yapan Sokollu Mehmed Paşa adına eşi Esmahan Sultan''ın Mimar Sinan''a yaptırdığı bu küçük külliye 1571''de tamamlandı. Kadırga''nın dik yokuşları arasına kurulan cami, eğimli araziyi ustaca kullanan avlusu ve merdivenleriyle Sinan''ın en zarif eserlerinden biri sayılır.

Küçük ölçeğine rağmen iç mekânı, mihrap duvarını kaplayan en kaliteli dönem İznik çinileriyle göz kamaştırır. Mihrap, minber ve giriş kapısının üzerinde Kâbe''deki Hacerü''l-Esved''den getirildiği bilinen küçük taş parçalar yerleştirilmiştir. Sultanahmet''ten birkaç dakikalık yürüyüş mesafesinde olmasına rağmen sakin kalan bir duraktır.'),
  ('sokollu-mehmed-pasa-camii', 'en', 'Built by Mimar Sinan for Grand Vizier Sokollu Mehmed Pasha, who served three sultans, and commissioned by his wife Esmahan Sultan, this small complex was completed in 1571. Set among the steep lanes of Kadırga, its courtyard and stairways make clever use of the sloping ground, and it is counted among Sinan''s most elegant works.

Despite its modest size, the interior dazzles with İznik tiles of the finest period covering the mihrab wall. Small fragments said to come from the Black Stone of the Kaaba are set into the mihrab, the pulpit and the entrance door. Only a few minutes'' walk from Sultanahmet, it remains remarkably peaceful.'),
  ('heybeliada', 'tr', 'Prens Adaları''nın ikinci büyüğü olan Heybeliada, uzaktan bakıldığında yere bırakılmış bir heybeye benzediği için bu adı alır. Çam ormanlarıyla kaplı tepeleri, sakin koyları ve tarihi köşkleriyle adaların en yeşil olanıdır. Ümit Tepesi''ndeki Aya Triada Manastırı ve buradaki tarihi Heybeliada Ruhban Okulu ile kıyıdaki Deniz Lisesi adanın simge yapılarıdır.

İskeleden başlayan ve adayı çevreleyen yol, yürüyüş ve bisiklet için idealdir; Değirmen Burnu''ndaki çamlık ve küçük koylar piknik ve deniz için sevilir. Cumhurbaşkanı İsmet İnönü''nün yazları kaldığı köşk bugün müze evdir. Büyükada''dan daha sakin ama ondan daha az yeşil olmayan bir gün için iyi bir seçimdir.'),
  ('heybeliada', 'en', 'The second largest of the Princes'' Islands, Heybeliada takes its name from its shape, which from afar resembles a saddlebag (heybe). With pine-covered hills, quiet coves and historic mansions, it is the greenest of the islands. The Hagia Triada Monastery with the historic Halki Seminary on Ümit Hill, and the Naval High School on the shore, are its landmarks.

The road that starts at the pier and circles the island is ideal for walking and cycling; the pine woods and small coves of Değirmen Point are popular for picnics and swimming. The house where President İsmet İnönü spent his summers is now a museum. It makes a calmer, equally green alternative to Büyükada.'),
  ('istanbul-arkeoloji-muzeleri', 'tr', '1869''da Müze-i Hümayun adıyla kurulan İstanbul Arkeoloji Müzeleri, Türkiye''nin müze olarak tasarlanmış ilk binasına sahiptir. Ressam ve arkeolog Osman Hamdi Bey''in öncülüğünde büyüyen koleksiyon, Balkanlar''dan Mezopotamya''ya uzanan geniş bir coğrafyadan bir milyonu aşkın eser barındırır. Ana bina 1891''de ziyarete açıldı.

Müze; ana bina, Eski Şark Eserleri Müzesi ve Çinili Köşk olmak üzere üç yapıdan oluşur. Ana binadaki Sayda kazılarından çıkan İskender Lahdi en ünlü parçadır; Eski Şark bölümünde ise bilinen en eski barış antlaşmalarından Kadeş Antlaşması''nın tableti sergilenir. Gülhane Parkı''nın girişinde, Topkapı Sarayı''nın hemen altında olduğundan aynı gün gezilebilir; rahat bir ziyaret için birkaç saat ayırın.'),
  ('istanbul-arkeoloji-muzeleri', 'en', 'Founded in 1869 as the Imperial Museum, the Istanbul Archaeology Museums occupy the first building in Turkey designed as a museum. Built up under the painter and archaeologist Osman Hamdi Bey, the collection holds more than a million objects from a vast area stretching from the Balkans to Mesopotamia. The main building opened to visitors in 1891.

The museum consists of three buildings: the main building, the Museum of the Ancient Orient and the Tiled Kiosk. The star of the main building is the Alexander Sarcophagus from the excavations at Sidon, while the Ancient Orient section displays the tablet of the Treaty of Kadesh, one of the oldest known peace treaties. It sits at the entrance to Gülhane Park just below Topkapı Palace, so both can be seen on the same day; allow a few hours.'),
  ('fethiye-camii', 'tr', 'Çarşamba semtindeki Fethiye Camii, 13. yüzyılın sonlarında Bizans soylusu Mihail Glabas Tarkaniotes''in yaptırdığı Pammakaristos Kilisesi''dir. Fetihten sonra bir süre Rum Ortodoks Patrikhanesi olarak kullanıldı, 16. yüzyılın sonunda III. Murad döneminde kazanılan zaferlerin anısına camiye çevrildi ve Fethiye adını aldı.

Yapının en değerli bölümü, yanındaki küçük şapelde (parekklesion) bulunan ve geç Bizans döneminden kalan altın zeminli mozaiklerdir; Kariye''deki mozaiklerle aynı dönemin ustalığını yansıtır. Ziyaret düzeni zaman zaman değiştiği için gitmeden önce kontrol etmekte yarar var. Fener ve Balat sokaklarına yürüme mesafesindedir.'),
  ('fethiye-camii', 'en', 'In the Çarşamba district, the Fethiye Mosque was originally the Pammakaristos Church, built in the late 13th century by the Byzantine noble Michael Glabas Tarchaneiotes. After the conquest it served for a while as the seat of the Greek Orthodox Patriarchate, and in the late 16th century, under Murad III, it became a mosque named Fethiye, ''of the conquest'', to celebrate military victories.

Its greatest treasure is the side chapel (parecclesion) with gold-ground mosaics from the late Byzantine period, reflecting the same mastery as those of Chora. Visiting arrangements change from time to time, so it is worth checking before you go. The streets of Fener and Balat are within walking distance.'),
  ('laleli-camii', 'tr', 'Sultan III. Mustafa''nın 1760-1763 yılları arasında Mimar Mehmed Tahir Ağa''ya yaptırdığı Laleli Camii, Osmanlı barok üslubunun İstanbul''daki en güzel örneklerinden biridir ve bulunduğu semte adını vermiştir. Adını, padişahın saygı duyduğu Laleli Baba adlı bir dervişten aldığı anlatılır.

Yüksek bir set üzerine oturan caminin altında bir zamanlar dükkânlar ve çarşı bulunan bir alt kat vardır; renkli mermerlerle süslü iç mekânı barok etkilerini açıkça gösterir. Bahçedeki türbede III. Mustafa ve oğlu III. Selim yatmaktadır. Ordu Caddesi üzerinde, Beyazıt ile Aksaray arasında kolayca uğranabilecek bir noktadadır.'),
  ('laleli-camii', 'en', 'Built for Sultan Mustafa III between 1760 and 1763 by the architect Mehmed Tahir Agha, the Laleli Mosque is one of the finest examples of Ottoman baroque in Istanbul and gave its name to the surrounding district. Its name is said to come from a dervish called Laleli Baba whom the sultan revered.

The mosque stands on a high platform with a lower level that once housed shops and a market, and its interior, decorated with coloured marble, shows clear baroque influences. The tomb in the garden holds Mustafa III and his son Selim III. It lies on Ordu Avenue between Beyazıt and Aksaray, an easy stop on the way.'),
  ('yeni-cami', 'tr', 'Eminönü meydanına hâkim olan Yeni Cami''nin temeli 1597''de III. Murad''ın eşi Safiye Sultan tarafından atıldı; ancak inşaat uzun yıllar durdu ve cami ancak 1665''te IV. Mehmed''in annesi Turhan Hatice Sultan''ın himayesinde tamamlanabildi. İstanbul''da Osmanlı hanedanının yaptırdığı büyük klasik camilerin sonuncusu sayılır.

Galata Köprüsü''nden ya da vapurdan bakıldığında basamaklı kubbeleriyle Haliç kıyısının simgelerinden biridir. İçeride İznik çinileri ve padişahın namaz kıldığı, ayrı girişli hünkâr kasrı dikkat çeker. Önündeki meydan ve güvercinler Eminönü''nün en canlı manzarasını oluşturur; Mısır Çarşısı hemen arkasındadır.'),
  ('yeni-cami', 'en', 'Dominating Eminönü square, the New Mosque was begun in 1597 by Safiye Sultan, wife of Murad III, but construction stalled for decades and it was only completed in 1665 under the patronage of Turhan Hatice Sultan, mother of Mehmed IV. It is considered the last of the great classical mosques built by the Ottoman dynasty in Istanbul.

Seen from the Galata Bridge or a ferry, its cascade of domes is one of the landmarks of the Golden Horn shore. Inside, look for the İznik tiles and the royal pavilion with its own entrance, where the sultan prayed. The square in front with its pigeons is one of the liveliest scenes in Eminönü, and the Spice Bazaar is right behind it.'),
  ('yerebatan-sarnici', 'tr', 'İmparator I. Justinianus döneminde, 6. yüzyılda şehrin su ihtiyacını karşılamak için Ayasofya''nın yakınına yapılan Yerebatan Sarnıcı, suyun içinden yükselen yüzlerce mermer sütunu nedeniyle halk arasında Yerebatan Sarayı diye anılır. Üzerinde eskiden bir bazilika bulunduğu için Bazilika Sarnıcı olarak da bilinir.

Loş ışıkla aydınlatılan sütun ormanı boyunca uzanan yürüme yollarından ilerlerken, sarnıcın kuzeybatı köşesinde sütun kaidesi olarak kullanılmış iki Medusa başını görebilirsiniz. Serin ve nemli iç mekân yazın ferahlatıcıdır. Gün içinde kuyruk oluşabildiğinden sabah erken ya da akşam saatleri daha rahattır.'),
  ('yerebatan-sarnici', 'en', 'Built in the 6th century under Emperor Justinian I to supply water to the city, the Basilica Cistern near Hagia Sophia is known locally as the Sunken Palace because of the hundreds of marble columns rising from its water. It takes its other name from a basilica that once stood above it.

As you follow the walkways through the dimly lit forest of columns, look for the two Medusa heads reused as column bases in the north-west corner. The cool, damp interior is refreshing in summer. Queues can build up during the day, so early morning or evening visits are easier.'),
  ('zeyrek-camii', 'tr', 'Haliç''e bakan bir yamaçtaki Zeyrek Camii, 12. yüzyılda İmparator II. Ioannis Komnenos ve eşi İrene''nin kurduğu Pantokrator Manastırı''nın kiliseleridir. Birbirine bitişik iki kilise ve aralarındaki şapelden oluşan yapı, Komnenos hanedanının mezar yeri olarak da kullanıldı ve Ayasofya''dan sonra İstanbul''da ayakta kalan en büyük Bizans dini yapısı sayılır.

Uzun bir restorasyonun ardından ibadete açılan caminin çevresindeki Zeyrek mahallesi, ahşap evleri ve dar sokaklarıyla UNESCO Dünya Mirası alanının bir parçasıdır. Yakındaki teras ve çay bahçelerinden Haliç, Süleymaniye ve Galata''yı birlikte gören güzel bir manzara vardır.'),
  ('zeyrek-camii', 'en', 'On a slope above the Golden Horn, the Zeyrek Mosque was once the church of the Pantokrator Monastery, founded in the 12th century by Emperor John II Komnenos and Empress Irene. Made up of two adjoining churches and a chapel between them, it also served as the burial place of the Komnenian dynasty and is considered the largest surviving Byzantine religious building in Istanbul after Hagia Sophia.

After a long restoration it has reopened for worship, and the surrounding Zeyrek neighbourhood, with its wooden houses and narrow lanes, is part of the UNESCO World Heritage Site. Terraces and tea gardens nearby offer a lovely view taking in the Golden Horn, the Süleymaniye and Galata.'),
  ('nuruosmaniye-camii', 'tr', 'Kapalıçarşı''nın Nuruosmaniye Kapısı''nın hemen yanındaki bu cami, 1748''de I. Mahmud döneminde başlanıp 1755''te III. Osman zamanında tamamlandı ve adını ondan alır: ''Osman''ın nuru''. İstanbul''da barok üslupla yapılan ilk büyük cami olması, onu Osmanlı mimarisinde bir dönüm noktası yapar.

Kavisli hatları, at nalı biçimli avlusu ve geniş pencerelerinden süzülen ışıkla aydınlanan iç mekânı, klasik Osmanlı camilerinden çok farklı bir hava taşır. Kapalıçarşı''ya girerken ya da çıkarken avlusunda soluklanmak için idealdir; Çemberlitaş Sütunu da birkaç adım ötededir.'),
  ('nuruosmaniye-camii', 'en', 'Next to the Nuruosmaniye Gate of the Grand Bazaar, this mosque was begun in 1748 under Mahmud I and completed in 1755 under Osman III, from whom it takes its name: ''the light of Osman''. As the first major mosque in Istanbul built in the baroque style, it marks a turning point in Ottoman architecture.

Its curving lines, horseshoe-shaped courtyard and interior flooded with light from large windows feel very different from the classical Ottoman mosques. Its courtyard is ideal for a breather on the way into or out of the Grand Bazaar, and the Column of Constantine is just a few steps away.'),
  ('rumeli-hisari', 'tr', 'Fatih Sultan Mehmed''in İstanbul''un fethinden önce, 1452''de Boğaz''ın en dar yerine birkaç ay gibi kısa bir sürede yaptırdığı Rumeli Hisarı, karşı kıyıdaki Anadolu Hisarı ile birlikte Karadeniz''den şehre gelebilecek yardımı kesmek için kuruldu. Bu yüzden Boğazkesen adıyla da anılır.

Yamaca yayılan surları ve üç büyük kulesiyle Boğaz''ın en etkileyici yapılarından biridir; kale içindeki basamaklar ve surlar boyunca yürüyerek Boğaz''ı ve Fatih Sultan Mehmet Köprüsü''nü yukarıdan görebilirsiniz. Müze olarak gezilir ve yazın açık hava konserlerine ev sahipliği yapabilir; ziyaret düzeni için gitmeden önce kontrol etmekte yarar var. Aşağıdaki sahil, Bebek ile Emirgan arasındaki yürüyüş yolunun en güzel kısmıdır.'),
  ('rumeli-hisari', 'en', 'Built by Sultan Mehmed II in just a few months in 1452, before the conquest of Constantinople, at the narrowest point of the Bosphorus, Rumeli Fortress worked together with Anadolu Fortress on the opposite shore to cut off help reaching the city from the Black Sea, earning it the name Boğazkesen, ''the strait-cutter''.

With its walls climbing the hillside and three great towers, it is one of the most striking sights on the Bosphorus; walking the steps and walls inside you look down on the strait and the Fatih Sultan Mehmet Bridge. It is visited as a museum and may host open-air concerts in summer; check visiting arrangements before you go. The shore below is the loveliest part of the walk between Bebek and Emirgan.')
  ) v(slug, lang, long_desc)
  join public.places p on p.slug = v.slug
 where t.place_id = p.id and t.lang = v.lang;
